INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter2-ikshvakus', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-ch2-ikshvakus-p1", "partName": "Sources for Ikshvaku History", "bodyMd": "Both archaeological and literary sources exist for Ikshvaku history.\n\n**Archaeological sources**\n\n*   Inscriptions, coins, monuments and pieces of architecture/sculpture.\n*   **Key inscription sites:** Nagarjunakonda, Jaggayyapeta (Krishna District), Ramireddi Palli, and Phanigiri.\n*   Inscriptions were written in Prakrit and the Brahmi script; from the time of **Ehuvala Santamula** onward, inscriptions began to be issued in **Sanskrit**.\n*   **Four classes of Ikshvaku inscriptions:**\n    1.  Carved Mahastupa and Ayaka Pillar inscriptions\n    2.  Chaityagriha inscriptions\n    3.  Detached pillar inscriptions\n    4.  Inscriptions on sculpture\n*   **Coins:** Found at Nagarjunakonda, Phanigiri, Nelakondapalli, Vaddemanu (Mahaboobnagar District) and Yeleswaram (Nalgonda District) — indicating the kingdom''s extent covered these areas. Unlike the Satavahanas, whose coins are found extensively, Ikshvaku coins are limited in number and small in size; the Ikshvakus did not issue gold or silver coins.\n*   At Nagarjunakonda itself, 148 coins of Satavahana kings have also been found, showing the site''s importance continued from Satavahana times. Roman coins were found too — coins of the Roman empress Tiberian Hedrian Faustina at Nagarjunakonda, and coins of Roman emperors such as Septimas Severes at Yeleswaram.\n*   **Religious/architectural remains:** Buddhist stupas, chaityas, toranas and sculptures at Nagarjunakonda, Ramireddi Palli, Nelakondapalli, Phanigiri and Anupu — informative about contemporary religious and social conditions.\n*   **Excavation history at Nagarjunakonda fort:** Buddhist stupas, viharas, chaityas, aramas, temples and bathing ghats of the Ikshvaku period (3rd century CE) have been unearthed here.\n    *   1926 — A. Ranaganadha Saraswati, Telugu Assistant in the Archaeological Department, first identified the remains at Nagarjunakonda.\n    *   1954 — Large-scale excavations carried out under Rayaprolu Subrahmanyam. Ancient sculptures, inscriptions and other objects were unearthed; some were shifted to the top of Nagarjunakonda hill, and some to the nearby Anupu.\n\n**Literary sources**\n\n*   **Puranas:** Matsya, Vayu, Brahmanda and Vishnu Puranas are important — they give the names of Ikshvaku kings and their periods of rule. Nearly all of them draw on information originally given in the Bhavishya Purana (written in the 2nd century CE). The Puranas provide dynastic details up to the 4th century CE, i.e., up to the start of Gupta rule (Chandragupta I).\n*   **Dharmamritam** (11th century CE Kannada work, based on an ancient Prakrit Kavya by Nyayasena): states that Yasodhara, an Ikshvaku king of Angadesa, established a kingdom at the mouth of the Krishna river, with Pratipalapuram (Bhattiprolu) as his capital.\n\n* * *", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-ch2-ikshvakus-p2", "partName": "Original Home of the Ikshvakus", "bodyMd": "There is no unanimous opinion among historians on the Ikshvakus'' original home.\n\n**\"Andhrabhrityulu\" theory:** In the beginning, the Ikshvakus were Andhrabhrityulu (servants of the Andhras) — they served as Mahatalavaras and Mahasenapatis under the Satavahanas. Like the Satavahanas, they had names starting with their mothers'' names and ending in \"anaka\" (with \"Skandha\"), showing clear Satavahana influence on their naming tradition.\n\n**Puranic tradition (North Indian origin):**\n\n*   Per the Vayu Purana, Ikshvakuvu was the head of the Suryavamsa, the eldest among Manuvu''s nine sons. He ruled with Ayodhya as his capital and had a hundred sons.\n*   After Ikshvakukuvu, Vikakshi (the eldest son) became king of Ayodhya. Of the remaining fifty sons, the rest became heads of smaller kingdoms in Northern India, and the remaining forty-nine princes established kingdoms in Southern India.\n*   Per the Vishnu Purana, the Kosala kingdom (Southern region) was established by Kusha, ruling from Kosasthali.\n*   Bauddhayana (a writer of the Dharmasastra) records the South Indian practice of marrying the daughter of one''s paternal aunt. Since Virapurushadatta married two daughters of his aunt, some scholars conclude the Ikshvakus were South Indians only — this marriage practice was not found among North Indians.\n\n**Linguistic/ethnic theories:**\n\n*   Stenkonow and Vogel: opined the Ikshvakus were Kannadigas (Western Deccan), placing them in the Dravidian language family.\n*   Dr. K. Rajagopalachari: stated the Ikshvakus were Tamils.\n*   Rapson and Buhler: opined the Ikshvakus came on exile from Kosala in Northern India.\n*   Kannada Jain work \"**Dharmamritam**\": states Yasodhara, king of Angadesa, established a kingdom at the mouth of the Krishna river, with Pratipalapuram (Bhattiprolu) as capital.\n*   Bishop Caldwell: stated the Ikshvakus were local Andhras only, not exiles from Northern India.\n*   B.S.L. Hanumantha Rao: opined the Ikshvakus were old local accountants, with \"Ikshu\" as their symbol.\n\n* * *", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-ch2-ikshvakus-p3", "partName": "Sriparvatiya Ikshvakus — Origin", "bodyMd": "Historians also differ on the meaning and origin of the term \"Ikshvakus.\"\n\n*   The Puranas and Buddhist works refer to them variously as Sriparvatiyas, Andhrabhrityas and Sriparvatiyandhras. The area from Nagarjunakonda up to the Nallamala hills surrounding Srisaila mountain was called **Sriparvata**.\n*   Prakrit inscriptions from **Jaggayyapeta and Nagarjunakonda** reveal that Srisantamula was an Ikshvaku Maharaja whose capital, Vijayapuri, lay on the western side of Sriparvata. During the 3rd and 4th centuries CE, Sriparvata itself carried the name Vijayapuri.\n*   Ikshvaku kings continued the Satavahana tradition of prefixing their mothers'' names before their own — a tradition that ended with them, as later dynasties (Pallavas, Brihatpalayanas, Anandagotris, Salankayanas) did not follow it.\n*   The titles \"Siri\" and \"Sami\" (as in Kodabalasiri, Santisiri, Hammasiri) indicate that the Ikshvakus were Satavahana bhrityas (servants/feudatories), and they also held the office of mahatalavara under the Satavahanas.\n*   **K.P. Jaiswal''s conclusion:** Ikshvakus and Sriparvatiyas are one and the same, and Sriparvatiyandhras were those belonging to the Andhra-Satavahana bhritya dynasty. Hence Sriparvatiyas, Ikshvakus and Andhrabhrityas are one and the same and not different — this is the settled scholarly position on the naming question.\n\n* * *", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-ch2-ikshvakus-p4", "partName": "Chronology of the Ikshvakus", "bodyMd": "There is no unanimity among historians regarding the exact rule period of the Ikshvakus, though the broad frame of 220–300 CE (80 years) is accepted.\n\n**Textual basis for chronology:**\n\n*   Matsya Purana states that after the Andhras, their bhrityas the Sriparvatiyas — seven kings in all — ruled for 52 years.\n*   Basing this on the word \"Dvipanchasatam\" in the Matsya Purana, Pargiter opined that either 52 years or 100 years should be considered.\n*   Inscriptions issued in the 13th regnal year of Santamula show he ruled for at least 13 years. After him, his son Virapurushadatta ruled for twenty years. The latter''s son, Ehuvala Santamula, ruled for 24 years. Per the Phanigiri inscription, Rudrapurushadatta reigned for 18 years.\n\n**D.C. Sircar''s reconstruction** (rule period at least 75 years, based on Nagarjunakonda inscriptions and the Virapurushadatta inscription):\n\n| Ruler | Reign (Sircar) |\n|---|---|\n| Virapurushadatta | 255 – 275 CE |\n| Ehuvala Santamula | 280 – 335 CE |\n| Rudrapurushadatta | 335 – 345 CE |\n\nSircar dated the Nagarjunakonda inscription to 278 CE and held that the Abhiras defeated the Ikshvakus and controlled Nagarjunakonda for five years (275–280 CE). Maremanda Rama Rao and V.V. Mirasi rejected this view, arguing that extensive Buddhist and Hindu construction during Virapurushadatta''s and Ehuvala Santamula''s reigns would not have been possible if an Abhira conquest had actually occurred. Rama Rao held instead that the kings named in the Abhira Vasusena inscription were relatives of the Ikshvakus, and that the inscription simply records their meeting on the occasion of the installation of the idol of Ashtabhuja Swamy.\n\n**P.V. Parabrahma Sastry''s chronology:**\n\n| Ruler | Reign |\n|---|---|\n| Santamula | 230 – 245 CE |\n| Virapurushadatta | 245 – 270 CE |\n| Ehuvala Santamula | 270 – 285 CE |\n| Rudrapurushadatta | 285 – 300 CE |\n\n**Final/accepted chronology used for the reign-by-reign account below** (220–300 CE, 80 years, per the Manchikallu inscription evidence for the Pallava invasion marking the kingdom''s decline around 300 CE, and no difference of opinion on the Satavahana fall being placed at 220–225 CE):\n\n| Ruler | Reign |\n|---|---|\n| Santamula | 220 – 233 CE |\n| Virapurushadatta | 233 – 253 CE |\n| Ehuvala Santamula | 253 – 277 CE |\n| Abhira Vasusena (interim rule) | 277/278 – 283 CE |\n| Rudrapurushadatta | 283 – 301 CE |\n\n* * *", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-ch2-ikshvakus-p5", "partName": "The Ikshvaku Rulers", "bodyMd": "### Caste of the Ikshvakus\n\nScholars hold differing opinions on the caste of the Ikshvakus — variously identified as brahmins, kshatriyas, or a local tribe.\n\n*   **Kshatriya claim:** Virapurushadatta claimed in his Nagarjunakonda inscription that the Ikshvakus were kshatriyas of the solar race, tracing descent from Sriramachandra of the Ikshvaku dynasty and from the lineage of Sakyamuni Gautama Buddha. Dr. Bhandarkar held that the Ikshvakus claimed descent from a kshatriya king of the solar family.\n*   **Local-tribe view:** The Ikshvakus were originally one of the local tribes. Ancient Indian kings customarily linked their dynasty to Puranic lineages for legitimacy.\n*   **Brahmin claim:** Since the Ikshvakus added their mothers'' brahmin gotra to their own names, some scholars concluded they were brahmins. King Santamula performed the Asvamedha, Vajpeya, Agnistoma and Agnihotra sacrifices; since only kshatriyas were traditionally held to perform such sacrifices, other scholars used this same evidence to argue the Ikshvakus were kshatriyas instead.\n*   **Bhandarkar''s mixed-lineage view:** The Ikshvakus may have descended from a mixed lineage — father a kshatriya, mother of brahmin caste. Bhandarkar further felt that the Ikshvakus may originally have belonged to local republican tribes and, after becoming rulers, attained social eminence and embraced brahmanism, much like the Satavahanas had done.\n\nAs per the inscriptions, information is available regarding only four Ikshvaku kings:\n\n1.  **Vasishtiputra Santamula** — 220–233 CE\n2.  **Madhariputra Virapurushadatta** — 233–253 CE\n3.  **Ehuvala Santamula** — 253–277 CE\n4.  **Rudrapurushadatta** — 283–301 CE\n\n### Vasishtiputra Santamula (220 – 233 CE)\n\nSantamula was the founder of the independent Ikshvaku kingdom. Joining with the Hiranyakas and members of the Pugiya dynasty, he dethroned Pulumavi IV, the Satavahana king, and declared independence. He brought Telangana and Coastal Andhra under his rule.\n\n*   **Inscriptions:** Found at Rentala and Kesanapalli. His greatness is described in the Nagarjunakonda inscriptions issued by his son, Virapurushadatta, which record that he donated crores of gold coins and thousands of cows, oxen, ploughs and acres of land.\n*   **Memorial sculpture:** On the fifth slab of his memorial stupa, Santamula is depicted clean-shaven, holding a stick, with deer skin over his shoulders, wearing ordinary clothes, barefoot, with an umbrella over his head; a servant holds a pot of water nearby, and among five Brahmins present, one receives his donation with the right hand — the scene depicts him performing the **Agnistoma sacrifice**.\n*   **Religion:** Santamula followed Vedic religion and is described in inscriptions as a worshipper of Skanda Kartikeya (Mahasena), whose worship was centred in Ujjain. He performed the Asvamedha, Agnistoma, Agnihotra and Vajapeya sacrifices — the Vajapeya being a sacrifice reserved for samrats (emperors) alone. An Asvamedha platform belonging to him has been unearthed in the Nagarjunakonda excavations. He held the title \"maharaja.\" No information survives on the extent of his empire beyond this.\n*   **Marriage alliances:** He had marriage alliances with the contemporary Pugiya and Danika dynasties.\n    *   His sister Santisri was married to Mahaskandhasri of the Pugiya dynasty, who held the ranks of Mahasenapati and Mahatalavari; inscriptions accordingly describe Santisri as Mahadanapatni and Mahatalavari. They had a son, Skandasagara.\n    *   Of his other sister, Harmyasri, details of her husband''s name and dynasty are not available.\n    *   Santamula gave his daughter, Adavi Santisri, in marriage to Skanda Visakhanaga of the Dhanika family, who held the ranks of Mahasenapati and Mahadandanayaka.\n    *   Although Santamula himself followed **Vedic religion**, both his sisters kept their faith in **Buddhism.**\n\n### Madhariputra Sri Virapurushadatta (233 – 253 CE)\n\nVirapurushadatta, son of Santamula, was the greatest ruler of the Ikshvaku dynasty. His inscriptions are found at Nagarjunakonda, Jaggayyapeta and Alluru.\n\n**Marriage alliances:** He contracted matrimonial alliances with several contemporary royal dynasties, whose support helped him establish a stable kingdom. As Per the Nagarjunakonda inscription, he had five wives, of whom four are named::\n\n*   Bapisri, daughter of his aunt (father''s sister) Harmasri\n*   Santasri, daughter of another aunt\n*   Mahadevi Rudrabhattarikaa, a Saka Kshatrapa princess of Ujjain, descended from Chasthana\n*   Mahadevi Bhattideva — his fifth wife\n\n**Daughter''s marriage:** His only daughter, Kodabalisri, was married to Vishnurudra Sivalananda Satakarni of the Chutu dynasty (Banavasi), the maharaja of Kuntaladesa. This was recorded in an **inscription issued by Kodabalisri** herself in the 11th regnal year of Ehuvala Sri Santamula.\n\n**Religion:** Virapurushadatta initially followed Vedic religion but later embraced Buddhism, and his reign is regarded as one of the brightest periods in the history of Buddhism in the Andhra region.\n\n*   A sculpture at Nagarjunakonda shows him touching a Sivalinga with his right leg. Some scholars once read this as evidence of Virapurushadatta forsaking Saivism, but it has since been established that the sculpture is only part of the Mandhata Jataka and does not actually relate to Virapurushadatta.\n*   His aunt Santisri was responsible for the Buddhist structures at Nagarjunakonda — during Virapurushadatta''s sixth regnal year, she built a Maha Chaitya at Nagarjunakonda over Buddha''s relics. As per the **Nagarjunakonda ' WHERE chapter_slug = 'telangana-history-en-chapter2-ikshvakus';
UPDATE theory_content SET concepts_json = concepts_json || 'inscription**, she had great affection towards Brahmins, sramans and poor people and longed for their welfare. During Virapurushadatta''s 18th regnal year, she issued another inscription wishing for his success, better health and longer life.\n*   Because of Santisri''s influence, the Ikshvaku queens — including the five wives of Virapurushadatta — honoured and patronised Buddhism.\n\n### Ehuvala Santamula (253 – 277 CE)\n\nEhuvala Santamula also called Vasishtiputra Bahubala Santamula or Santamula II, he was the son of Mahadevi Vasishtibhattideva and Virapurushadatta.\n\n*   **Naming tradition:** The tradition of adopting the **grandfather''s name** began with the **Ikshvakus**; it was later followed by the Guptas, Vakatakas, Pallavas, Vishnukundus and Salankayanas.\n*   **Military affair:** His inscriptions have been found in the Nagarjunakonda excavations. One inscription records that before his 11th regnal year, a battle was fought in which his commander-in-chief Elisri achieved victory, attributed to the mercy of Kartikeya. This inscription was issued by Elisri himself in Ehuvala Santamula''s 11th regnal year. Elisri is also credited with building Yeleswaram town and constructing a Saiva temple there known as \"Sarvadevalaya.\"\n*   **Abhira Vasusena episode:** An inscription found in the Nagarjunakonda excavations, issued by Abhira king Vasusena in his 30th regnal year, references Avanti king Saka Rudradaman, the Abhira king Vasusena, and Vishnurudra Sivalananda Satakarni, king of Banavasi (Chutu) — recording that they installed the idol of Ashtabhujaswami. Since the reigning Ikshvaku king''s name is notably absent from this inscription, it has given rise to considerable scholarly doubt.\n    *   D.C. Sircar''s view: these kings supported Abhira Vasusena''s invasion against the Ikshvakus in capturing Vijayapuri, where they installed the idol of Ashtabhujaswami; the Abhiras ruled the Nagarjunakonda region for some years thereafter. Since the inscription of Abhira Vasusena is found in the very capital of the Ikshvaku kingdom, it has to be regarded as evidence of his invasion.\n*   **Language shift:** By Ehuvala Santamula''s time, **Sanskrit** had become stabilised as the court language in place of Prakrit.\n*   **Religion:** He followed the Vedic religion and was a devotee of Swami Mahasena. During his reign, the Kartikeya temple, Pushpabhadraswami temple, Nodigiswara temple and Devi temple, among others, were built at Vijayapuri.\n\n### Rudrapurushadatta (283 – 301 CE)\n\nBasing on the script found on coins recovered at Gurajala (Guntur District), Nagarjunakonda and Phanigiri, and on the name found in the inscriptions, historians have identified Rudrapurushadatta as the last Ikshvaku king. He was the son of Ehuvala Santamula. An inscription records that in his fourth regnal year, one Nodukasri donated land to his god Halampuraswamy — an event historians have identified with Nagulapuram in Guntur District.\n\n### Virapurushadatta II\n\nThe brother of Rudrapurushadatta, he is learnt from inscriptions to have died while still Yuvaraja (crown prince), never having ruled as king.\n\n### Decline of the Ikshvaku Kingdom\n\nThe Ikshvaku kingdom declined due to **Pallava aggression** from Kanchi. The Pallavas went on to occupy Vijayapuri, the Ikshvaku capital.\n\n*   The inscription of Pallava Simhavarma was found in Manchikallu village, Guntur District. The script of this inscription, which is in Prakrit, resembles the script of the Ikshvaku inscriptions. Among Pallava inscriptions found so far, this is the oldest — and its discovery so near the Ikshvaku capital indicates that a Pallava invasion did take place.\n*   With Pallava decline → their feudatories, the Brihatpalayanas in the Krishna valley and the Anandagotris in Guntur mandal, declared their independence.\n\n* * *", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-ch2-ikshvakus-p6", "partName": "Administrative Organization", "bodyMd": "The Ikshvakus adopted the Satavahana administrative system with only minor changes.\n\n### Central Government\n\n*   The king was the supreme authority and a despot in administration, with all powers vested in his hands. He carried on administration as detailed in the Dharmasastras and Smritis, including duties towards the Brahmins.\n*   Kings issued inscriptions describing their own victories and praising the greatness of their fathers and grandfathers. **Vasishtiputra Santamula** assumed the title \"**maharaja.**\"\n*   Kings showed active interest in conquering neighbouring kingdoms; Asvamedha, Vajapeya and Agnistoma sacrifices were performed as signs of victory.\n*   **Divine right monarchy:** a principle that existed in seed form during Satavahana times became clearly established by the time of the Ikshvakus. Through Vedic sacrifices, later kings declared themselves divine right monarchs; ministers and officials held that the king was the personification of God on earth, and that opposing the king amounted to opposing God.\n*   **Key officials:** mahatalavara, mahasenapati, mahadandanayaka and kostagarika (treasurer). One person often held two or more of these posts simultaneously — e.g., Vasishtiputra Skandasri of the Pugiya family and Vasishtiputra Skandachaliki Remmanaka of the Hiranya family held the titles of mahasenapati, mahatalavari and mahadandanayaka together.\n    *   **Mahatalavaras** were officials with feudatory status, responsible for maintaining law and order.\n    *   **Mahasenapati and Mahadandanayaka** were part of the Central Government — the Mahasenapati looked after military affairs, while the Mahadandanayaka conducted criminal trials and discharged judicial duties.\n    *   Officials frequently had marriage alliances with the royal family.\n\n### Local Government\n\n*   The empire was divided into **rashtras**. Allur and Amaravati inscriptions refer to \"rattha\" (rashtra). A rashtra consisted of several villages and was the equivalent of the \"**ahara**\" of Satavahana administration.\n*   Names of rashtras found in inscriptions include Pugi rashtra, Hiranya rashtra and Munda rashtra.\n*   \"Rathikudu\" and \"rathi,\" found in Ikshvaku inscriptions, refer to the administrator of a rashtra.\n*   Rashtras were divided at different levels with different names: five villages together were called \"**grama panchaka**.\"\n*   The administrative division \"**mahagrama**\" was kept under the control of an official called _**mahagramika**_.\n*   Village administration authority was hereditary. Ikshvaku inscriptions refer to \"**Talavara**\" as the village official; one who had authority over several village officials could be termed \"mahatalavari.\"\n\n### Judicial Administration\n\n*   The king was the highest judicial authority. The Mahadandanayaka conducted trials of crimes at the Centre and imposed punishments. Special courts also existed for judicial trials.\n*   Punishments were severe: for treason and offences against the king, the death sentence was imposed; for smaller offences, fines and beating with sticks were used.\n*   Sources on the Ikshvaku judicial system are limited, but the Palamur inscription of Madhava Varma III (Vishnukundi king, post-Satavahana age) describes several divine tests used to decide guilt, which he claims to have held personally. **Nine types of divine tests (divya):**\n    1.  **Tula-divya** — weighing the criminal to decide culpability\n    2.  **Agni-divya** — the accused walks on fire without getting burnt\n    3.  **Jala-divya** — arrows sent into water must be retrieved by diving in\n    4.  **Visha-divya** — the accused must take a ring out of a pot containing a cobra, without being bitten\n    5.  **Kosa-divya** — the accused must drink the water used to clean idols of gods/goddesses and survive\n    6.  **Tandula-divya** — rice over which mantras were administered must be chewed\n    7.  **Tapta maska-divya** — a coin must be taken out of boiling oil\n    8.  **Phala-divya** — a burning iron rod must be held, then grain pressed hard in the same hand\n    9.  **Dharmadharma-divya** — idols personifying dharma and adharma are placed in a jar; the idol the accused draws out decides the crime/guilt\n\n### Army Organization\n\n*   The Ikshvakus followed the Satavahana army organisation, with the traditional four-fold division: **chariots, elephants, cavalry and infantry.**\n*   When the king was on expedition, villagers were required to supply the army''s daily needs (milk, curd, vegetables) as well as sitting material and cots.\n*   Army strength and victories were central to a kingdom''s survival, so army maintenance received the highest percentage of the kingdom''s revenue.\n*   The king himself typically led the army at war. Enemy military strengths and weaknesses were gathered through spies, and battle plans were made accordingly.\n*   Swords and spears were the main weapons; headgear and shields provided protection; arrows were also used. Wars caused heavy damage to crops in nearby villages and brought losses and a frightful atmosphere for the people.\n\n### Income and Expenditure\n\n*   **Land revenue (\"bhaga\")** was the chief source of revenue — the king''s \"share,\" generally 1/6th of the crop.\n*   **\"Bhoga\"** was another land tax, collected by local administrators and enjoyed by them.\n*   **\"Deyam\"** (cash) and **\"meyam\"** (kind) were also collected.\n*   **\"Kara\"** was a tax levied on industries, crafts and trade; taxes were also levied on commercial items such as salt and sugar.\n*   Duty was levied on highways. Forests and green plains belonged to the king. Tax was collected on water supplied for irrigation.\n*   Among taxes levied in kind, an important one concerned cattle — agriculturists had to give the first calf born to their cows to the government as a duty (per Mirasi).\n*   **Expenditure was in four parts:**\n    \n    1.  Maintenance of the government, army maintenance, and salaries/allowances for officials\n    2.  Temple construction, worship of gods and goddesses, and celebrations\n    3.  Patronage of poets, scholars and intellectuals\n    4.  Gifts to different religions\n    \n    *   Additionally, money was spent on constructing tanks and canals to aid the growth of agriculture, since it employed the largest number of people.\n\n* * *", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-ch2-ikshvakus-p7", "partName": "Social Conditions", "bodyMd": "*   Post-Satavahana society retained the four varnas, but several mixed castes and sub-castes emerged. Every person adopted the occupation of their ancestors at birth and received the attached social status; in the later period, castes formed on occupational lines.\n*   As per Nagarjunakonda inscriptions, distinct social branches existed: Pugiyulu, Hiranyakulu, Mundalu, Dhanikulu, Nagulu, Selakulu and Kulahakulu. The Ikshvakus contracted marriage alliances with local families such as the Pugiyas and Hiranyakas, and with Ujjain Kshatrapas.\n*   **Brahmins:** their position improved through the performance of Vedic rituals by Ikshvaku kings, their employment in higher posts, and temple construction, all of which improved their economic condition. Kings gave land to Brahmins.\n    *   King''s officials were not to enter such donated villages; these villages had exemption from 18 types of taxes, and the donee (recipient) gradually grew enriched. These lands were cultivated only by Sudras.\n    *   A class of feudal lords emerged between the king and the people.\n    *   Based on the Vedic branch studied and the dharma sutras followed, Brahmins came to be divided into three branches: Vedic scholars, temple priests, and employees of the king.\n    *   By the 2nd century CE, foreign communities such as Sakas, Yavanas, Pahlavas and Abhiras had become sanskritised and joined the Indian stream of life; because they were rulers, they received kshatriya social status.\n*   **Sudras:** gained political emergence, and patronised Brahmins performing Vedic rituals also came to be considered kshatriyas.\n*   **Vaisyas:** resorted to trade and business; large businesses were run only by merchant associations, which formed into guilds. Besides Vaisyas, weavers, oil extractors and blacksmiths also conducted trade.\n*   The majority of people in society were **Sudras**, following diverse occupations. Agriculturists were called \"**halikas**.\" There were many handicraft persons — blacksmiths, potters, carpenters, weavers, washermen, barbers and leather workers.\n    *   Inscriptions of this age record donations made to the \"rathakarulu.\" These craftspeople, even today, wear the sacred thread (yagnopaveetam) and call themselves Viswabrahmins, descendants of Viswakarma. Goldsmiths, blacksmiths, kanchara, kasi (workers) and carpenters were regarded as one and the same group; kings also granted them lands.\n*   **Women:** Amaravati and Nagarjunakonda inscriptions record that women of high families made independent donations even during Ikshvaku times. Women of the royal family made free donations for the mahachaitya at Nagarjunakonda. Although Ikshvaku kings followed Vedic religion, women of their families patronised Buddhism, building many chaityas and making donations. Like the Satavahanas, Ikshvaku kings continued to add their mother''s name before their own.\n\n* * *", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-ch2-ikshvakus-p8", "partName": "Economic Conditions", "bodyMd": "### Feudalism\n\n*   The post-Satavahana state system depended on feudalism, based on the theory that the king was overlord of all land — reinforced by the system of divine right monarchy.\n*   As kings freely declared village donations to Brahmins and religious organisations, ryots (cultivators) lost their earlier rights over the land they cultivated and were reduced to the status of agricultural serfs, while the donees gained all rights over the land.\n*   In the later period, higher officials in the administrative machinery, instead of receiving salaries, were given lands yielding equivalent income.\n*   Since agriculture was vital for government revenue, kings made efforts to develop it. Santamula donated lakhs of ploughs, cows, oxen and gold. Forests were cleared and new lands brought under cultivation; canals and tanks were dug for irrigation, and evidence of such artificial construction has been unearthed at Nagarjunakonda.\n*   Land grants by kings also contributed to agricultural development — Brahmins, who received such lands, possessed knowledge of seasons, panchangam (calendar) and seeds, and the effects of soils. Donated lands were exempt from 18 types of taxes (this fact is corroborated by the Hirahadagalli and Maidavolu inscriptions of Pallava Sivaskanda Varma), and even the king''s own officials were barred from entering such donated villages.\n*   Under the new land relations of the post-Satavahana age, feudalism took root: local chiefs remained o' WHERE chapter_slug = 'telangana-history-en-chapter2-ikshvakus';
UPDATE theory_content SET concepts_json = concepts_json || 'bedient to the king and paid tribute, maintaining the army and supplying it to the king in times of war; village officials, in turn, remained obedient to the local chief and remitted part of their revenue to him.\n\n### Agriculture: Crops\n\nAgriculture became the main source of livelihood for the people.\n\n*   **Main crops:** paddy, wheat, sugarcane; dry crops such as bajra and ragulu; pulses like red gram; oil seeds such as castor; cattle fodder crops like jute and cotton.\n*   Cotton was cultivated both as a dry crop and a wet crop.\n*   Coconut, a commercial crop, contributed to the economic development of coastal areas. The **Nasik inscription** records that the **Saka ruler Rishabhadatta** had donated two coconut gardens to Brahmins, consisting of 32,000 coconut trees in one garden and 8,000 in another.\n*   Since transport facilities and sea voyages were not well developed in that period, local markets alone served as trading centres for crop production.\n\n### Handicrafts and Guilds\n\n*   Excavations at Nagarjunakonda unearthed houses of craftsmen; one house yielded goldsmith''s craft materials such as \"atchulu\" and \"musalu.\" Several types of gold and silver artistic objects were found.\n*   Ikshvaku inscriptions refer to the Parnika Sreni (betel leaf craftsmen''s guild) and the Pusika Sreni (confectioners'' guild); another inscription mentions \"Kulika Pramukhudu\" (leader of the guild).\n*   The **Vilopatti inscription** indicates that handicraft industries continued in villages.\n\n### Internal and External Trade\n\n*   Trade with Rome continued during Ikshvaku times; Roman coins found at Nagarjunakonda confirm this. Vijayapuri (Nagarjunakonda) itself functioned as a Roman trade centre.\n*   Internal and external trade was controlled by **Vaisyas**.\n*   While Satavahana coins found in Telangana and Andhra Pradesh are numerous, post-Satavahana royal dynasty coins are very few. After the Satavahanas, no ruler issued coins bearing the figure of a ship.\n*   After the 3rd century CE, trade with the Roman empire continued but mostly through land routes rather than sea routes as before — as a result, trade centres of North India gained greater importance.\n*   A **Nagarjunakonda inscription** issued in the 14th regnal year of Ikshvaku king Virapurushadatta refers to **Ghantasala**, which prospered as the main port owing to its location at the main entrance of the Krishna river. Ports continuing from Satavahana times included Barukachham (Broach), Kalyani (Maharashtra), Sopara and Mysolea (Machilipatnam).\n*   **Exports from India:** spices, iron, steel, hand-woven clothes, coconuts.\n*   **Imports into India:** gold, silver, copper, intoxicants and glass material.\n\n* * *", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-ch2-ikshvakus-p9", "partName": "Cultural Development", "bodyMd": "During Ikshvaku rule, literature, architecture and art achieved remarkable progress. Vedic, Buddhist and Jain religions all flourished. Though Prakrit remained the official language, Sanskrit achieved good patronage and development. Buddhist stupas, viharas, chaityas, and the Navagraha and Sarvadevalaya Hindu temples serve as mirrors of the styles of architecture and sculpture of the age.\n\n### Religious Development — Buddhism\n\n*   Among the Ikshvaku kings, all except Virapurushadatta were followers of Vedic religion; however, their queens patronised Buddhism and made donations.\n*   By the 2nd century CE, Nagarjunakonda had become a famous Buddhist arama in India itself.\n*   **Buddhist sects at Nagarjunakonda:** Among the Mahasanghikas, the sects Poorvasaileeyulu (Pubbasailulu), Aparasaileeyulu and Bahusruteeyulu emerged — Amaravati and Nagarjunakonda served respectively as the main centres for Poorvasaileeyulu and Aparasaileeyulu. Other sects present at Nagarjunakonda included Rajagirikulu, Mahisasakulu and Siddhantikulu.\n*   Virapurushadatta''s period is regarded as the brightest one for Buddhism. His aunt Santisri, during his sixth regnal year, built a mahachaitya at Nagarjunakonda containing the dhatuvu (relics) of Buddha and erected nine ayaka pillars. She took pity on Brahmins, sramans and poor people and made several donations, wishing that all people and beings should be happy in both worlds — a sentiment reflecting Mahayana Buddhism''s emphasis on the welfare of all rather than of the self alone. The Buddhist sculptures found at Nagarjunakonda testify to the flourishing of Mahayana Buddhism there.\n*   Not only royal ladies but also common ladies made donations to Buddhist viharas and issued inscriptions — e.g., Upasika Bodisri, niece of Bodisarma (treasurer of the kingdom), built a vihara at Chuladammagiri in Vijayapuri, which became famous as the **Simhala Vihara**. Buddhist propagators from Ceylon were said to propagate dharma in Kashmir, Gandhara, China, Chilata, Tosali, Aparanta, Vanga, Vanavasa, Yavana, Damila and Palura. Kodabalisri, daughter of Virapurushadatta, is recorded to have built a vihara for the Mahisasakas. During Ehuvala Santamula''s time, his mother Mahadevi Bhattideva built a mahavihara and mahachaitya for the Bahusrutiyas.\n*   Buddhistic relations existed between Simhalam (Ceylon) and Nagarjunakonda, with Buddhist monks from Sri Lanka regularly visiting. As per Nagarjunakonda inscriptions, Mahasanghika Acharyas are recorded to have known by heart the Dighanikaya and Majjimanikaya, two of the five nikayas.\n*   **Chief Buddhist centres:** in Andhra Pradesh — Nagarjunakonda, Jaggayyapeta, Chinaganjam, Ramireddi Palli and Bavikonda; in Telangana — Nelakondapalli, Tummalagudem and Gajulabanda (Nalgonda District).\n*   As per the Digha and Majjima nikayas, Badanta Ananda belonged to the Aparamahavina saileeya branch and lived in the 3rd century CE. It was possibly on his persuasion that Virapurushadatta embraced Buddhism.\n*   Aryadeva, Dharmanandi and Badanta Ananda were disciples of Nagarjuna. Aryadeva wrote a work titled \"**Chittasuddhi Prakarana**.\" Because he made light of Vedic practices, he was murdered at the hands of Vedic followers.\n*   **Later Buddhist figures (post-Satavahana age, 3rd–early 7th century CE):** Bhavaviveka, Buddhaghosha, Dharmakirti and Siddha Nagarjuna carried on their activities in this period.\n    *   **Bhavaviveka** (5th century CE) wrote a commentary called \"Pragna Pradeepa\" on Nagarjuna''s Madhyamika Sastra.\n    *   **Buddhaghosha** was to Theravada (Hinayana) Buddhism what Acharya Nagarjuna was to Mahayana. He went to Sri Lanka intending to translate \"**Atta Kathalu**\" (written in the Sri Lankan language) into Prakrit; living at Anuradhapura Vihara, he instead wrote the work \"Visuddhamogga\" for the Theravadis there.\n    *   **Dharmakirti** was educated at Nalanda University and was a disciple of Dharmapala of Kanchi; he earned great name and fame in the world of Buddhist dharma.\n    *   **Siddha Nagarjuna** resided at Dhanyakatakam and Sriparvata. He belonged to the Vajrayana sect, which stood for tantric vada (based in mantras, tantras and magic). The Ramireddipalli inscription records that he was a Telugu person; he received rasasiddhi, swarnasiddhi and Vajrayana siddhi.\n    *   **The five acts (Pancha-makara) of Vajrayana practitioners:** madhuvu (taking intoxicating drink), mamsam (meat eating), matsyam (eating fish), mudra (body posture) and maithinam (sexual intercourse). Followers justified these acts by holding that ordinary moral principles and regulations did not apply to them.\n    *   Dhanyakatakam, Sankhavaram, Ramatirtham and Salihundam remained centres of Vajrayana practice.\n*   Buddhism, which enjoyed royal patronage and popular support during Ikshvaku times, started declining in the later period.\n\n### Religious Development — Jainism\n\nDuring the time of the Ikshvakus, Penugonda, Pithapuram, Nedunuru, Tatipaka, Aryavatam and Draksharamam were the main centres of Jainism. At Aryavatam, statues of six Tirthankaras belonging to the 3rd century CE have been found.\n\n### Religious Development — Puranic Hinduism (Saivism, Vaishnavism)\n\n*   Ikshvaku king Srisantamula performed Vedic sacrifices like Asvamedha, Vajapeya, Agnistoma and Agnihotra. He was a devotee of the Puranic gods Virupakshapati (Siva), Mahasena (Skanda) and Kartikeya.\n*   **Ehuvala Santamula** constructed a Siva temple named Pushpabhadraswamy at Nagarjunakonda. His commander-in-chief Elisri built a Siva temple for Kumaraswamy named \"Sarvadeva.\"\n*   A temple named \"Nodagisvara\" existed at Nagarjunakonda; a merchant''s daughter, Ratavasya, together with others, made donations to Nodageswaraswamy, per an issued inscription.\n*   **Sivasena**, commander-in-chief of Abhira Vasusena, is recorded (in an inscription he issued) to have built a Vaishnava temple at Nagarjunakonda known as \"Ashtabhujaswamy,\" during his attack on the Ikshvaku kingdom in the time of Ehuvala Santamula.\n*   **Mother Goddess worship** also existed during Ikshvaku times — a Hariti temple was built at Nagarjunakonda, and inscriptions record that women, for begetting children, used to offer bangles at the Saptamatrikas in the Hariti temple.\n*   Puranic, Saiva, Vaishnava and Sakteya religions were all honoured during Ikshvaku times; Skanda, Ganapati, Yaksha, and Hariti gods and goddesses were worshipped.\n\n### Language and Literature\n\n*   Though Prakrit was the official language during the time of the Ikshvakus, from the 4th century CE onward, Sanskrit occupied the place of Prakrit in inscriptions and literature.\n*   Inscriptions issued before Ehuvala Santamula''s 11th regnal year were in Prakrit; those of the later period were in Sanskrit. **Inscriptions of Virapurushadatta**, who ruled before Ehuvala Santamula, were in Sanskrit. The Sarvadeva inscription issued by Elisri, commander-in-chief of Ehuvala Santamula, was also in Sanskrit.\n*   Contemporary regional evidence: the Kondamudi inscription of Jayavarma, the Brihatpalayana king, was in Prakrit; the Salankayanas and Anandagotris used both Prakrit and Sanskrit in their inscriptions; all inscriptions of the **Vishnukundus were in Sanskrit**.\n*   Sanskrit received royal patronage; kings donated villages and lands to Vedic scholars. During Ikshvaku times, famous universities flourished at Dhanyakatakam (Amaravati) and Nagarjunakonda.\n*   **Udyotana**, who belonged to the 8th century CE, in his work \"Kuvalayamala,\" records that Buddhist monks from Sri Lanka, Tibet, Nepal and all regions of India used to come to Nagarjunakonda for education.\n*   Aryadeva, disciple of Acharya Nagarjuna, wrote the work \"**Chittasuddhi Prakaranam.**\"\n*   **Ikshvaku inscriptions** contain references to sciences such as Astronomy, Medicine and Mathematics.\n*   **Hiuen-tsang**, the Chinese traveller who visited India in the 7th century CE, recorded that the **Sriparvata Vihara** had by then been subjected to lack of patronage.\n\n### Architecture and Sculpture\n\n*   In the 3rd and 4th centuries CE, Buddhist arts and the style of architecture flourished gloriously; even though the Satavahana empire had declined, the arts of architecture and sculpture did not become extinct.\n*   **Nagarjunakonda excavations** unearthed 3rd-century-CE structures including: an impregnable fort, a moat, many buildings inside the fort, an open-air stadium, the Asvamedha platform of Santamula, and Buddhist stupas, viharas, chaityas, aramas, temples and bathing ghats.\n    *   The playground/stadium was constructed in different stories — no similar structure has been unearthed anywhere else in India. Some scholars believe it may have been built with the help of Roman experts.\n    *   Approximately 30 Buddhist aramas existed at Nagarjunakonda, built by adherents of different Buddhist branches. Nagarjunakonda stands as testimony to the changes that came about within Buddhism, as the impact of branches such as Aparamahavinasaileeya, Maha Viharavasini, Mahisasika and Bahusruteeya fell upon its architecture and sculpture.\n    *   Earlier, there had been a taboo on depicting Buddha in human form; because of support from the **Aparamahavinasaileeya branch**, statues of Buddha came to be carved in a beautiful, humanised manner.\n*   **Buddhist stupas and viharas built in the 3rd century CE** existed in Telangana at Nelakondapalli (Khammam District), Gajulabanda (Nalgonda District), Tummalagudem (Nalgonda District) and Nandikonda (Nalgonda District); in Andhra Pradesh at Goli, Chandavaram, Dupadu, Namburu, Uppugunduru and Rentala.\n*   **Three types of stupas at Nagarjunakonda:**\n    1.  Stupas built over the remains of body parts of Buddha or a leading Buddhist monk (bones, teeth, hair, nails, etc.)\n    2.  Stupas built over the begging bowls and articles used by Buddhist monks\n    3.  Stupas built as memorials of Buddha or his disciples, without remains or objects\n*   The Amaravati tradition of sculpture continued through the last phase into Ikshvaku times, reaching its greatest heights in the construction of Nagarjunakonda sculpture, which became the centre for this art form.\n    *   The practice of sculptors depicting Buddha in the form of emblems continued: his feet, a horse, the bodhi tree, the dharmachakra, a stupa and the trisula relating to his life were carved as emblems.\n    *   Stories such as the meeting of Buddha, Yasodhara and Rahul; the Sibi Jataka; and the Mandhata Jataka, among others, were carved in the chaityas at Nagarjunakonda, Ghantasala, Gummadidurru and Goli.\n    *   Masterpieces of Ikshvaku sculpture include images of Buddha, Santamula''s memorial pillar, depictions of Virapurushadatta''s hatred toward brahmana religion and his embrace of Buddhism, Virapurushadatta suppressing a rebellion, and erotic sculptures.\n*   **Nelakondapalli:** the most important stupa built during the post-Satavahana period. A mahastupa, viharas of the Chatussala type, and many man-sized Buddha statues have been unearthed here, constructed between the 3rd and 6th centuries CE. A bronze statue of Buddha and nine marble statues of Buddha were also unearthed. Because marble pieces and water containers were found near where the statues were located, V.V. Krishna Sastry opined that this was a factory where Buddha statues were prepared. Nelakondapalli Buddha images stand as specimens of Amaravati-style sculpture.\n*   **Gajulabanda:** Buddhist stupa, vihara and chaitya remains have come to light; dolls of two lions made of limestone have also been found here.\n*   **Nandikonda:** some Buddhist structures have been unearthed.\n*   **Hindu temple architecture** also commenced during Ikshvaku times. Remains at Nagarjunakonda show temples of Kartikeya, Pushpabhadra, Ashtabhujaswamy, Hariti, Kubera and the Navagrahas built during Ehuvala Santamula''s time. The Sarvadeva temple was built at Yeleswaram (Nalgonda District). Nagarjunakonda temples were built per agama sastra, with sanctum, antarala, mantapa, dhvaja stambha and prakara (compound wall).\n*   ' WHERE chapter_slug = 'telangana-history-en-chapter2-ikshvakus';
UPDATE theory_content SET concepts_json = concepts_json || 'The practice of depicting stories from the Itihasas and Puranas in temple sculpture continued during Ikshvaku times. In the female sculptures at Nagarjunakonda, erotic appeal became more pronounced, and women''s sculptures were carved in a slim and attractive manner.\n\n* * *", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-ch2-ikshvakus-p10", "partName": "Summary", "bodyMd": "The Ikshvakus began their authority as feudatories of the Satavahanas and, after the latter''s decline, established independent rule while carrying forward the Satavahana administrative system and cultural trends — including, like the Satavahanas, prefixing their mothers'' names before their own. \n\nThrough marriage alliances with nearby royal dynasties, they worked to secure and expand their authority. By freely making donations of land along with oxen, ploughs and cows in the thousands, Ikshvaku rulers demonstrated their commitment to agricultural development, backed by the construction of tanks and canals. During their rule, Sudras and women gained a degree of independence and progress in the social sphere. \n\nIn the economic sphere, besides agriculture, handicraft industries and internal and external trade developed, with foreign trade carried on with Rome and Ghantasala — at the mouth of the Krishna river — serving as the main port. The spread of Buddhism, Jainism, Saivism and Vaishnavism contributed to the spread of the Sanskrit language and to progress in architecture and sculpture. \n\nThe Buddhist stupas, viharas, memorial emblems, and Saiva and Vaishnava temples that the Ikshvakus built at places like Amaravati, Nagarjunakonda, Nelakondapalli, Tummalagudem and Gajulabanda stand as ample testimony to their contribution to art and cultural development.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter2-ikshvakus';
